WITH scored AS (SELECT *, NTILE(5) OVER w_hist humidity_bucket, AVG(temp_c) OVER (PARTITION BY device_code ORDER BY status_bits, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) temp_c_avg_6, CUME_DIST() OVER w_grp humidity_cume_dist, CORR(pressure, status_bits) OVER (PARTITION BY device_code) corr_pressure_status_bits, PERCENT_RANK() OVER w_recent status_bits_percent_rank FROM device_readings WINDOW w_hist AS (PARTITION BY device_code ORDER BY humidity DESC, id), w_grp AS (ORDER BY humidity NULLS LAST), w_recent AS (PARTITION BY device_code ORDER BY status_bits)) SELECT CASE WHEN humidity_cume_dist >= 0.7 THEN 'PREMIUM' ELSE 'STANDARD' END AS humidity_cume_dist_tier, device_code, ROUND(AVG(humidity), 2) AS avg_humidity, PERCENTILE_APPROX(humidity_bucket, ARRAY(0.25, 0.5, 0.75)) AS humidity_bucket_quartiles, RANK() OVER (PARTITION BY CASE WHEN humidity_cume_dist >= 0.7 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY ROUND(AVG(humidity), 2) DESC) AS avg_humidity_rank FROM scored GROUP BY humidity_cume_dist_tier, device_code ORDER BY avg_humidity DESC
